import{_ as s,o as e,c as i,al as l}from"./chunks/framework.BawR2jEz.js";const k=JSON.parse('{"title":"Глобальные поля","description":"Поля, доступные на всех страницах сайта через ex.global_fld() — телефон, адрес, логотип и другие.","frontmatter":{"title":"Глобальные поля","description":"Поля, доступные на всех страницах сайта через ex.global_fld() — телефон, адрес, логотип и другие."},"headers":[],"relativePath":"fast-settings/global-fields.md","filePath":"fast-settings/global-fields.md"}'),t={name:"fast-settings/global-fields.md"};function n(h,a,r,o,d,p){return e(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="глобальные-поля" tabindex="-1">Глобальные поля <a class="header-anchor" href="#глобальные-поля" aria-label="Permalink to &quot;Глобальные поля&quot;">​</a></h1><p>Поля, не привязанные к конкретному блоку или рубрике. Доступны на любой странице сайта через Twig-функцию <code>ex.global_fld()</code>.</p><h2 id="концепция" tabindex="-1">Концепция <a class="header-anchor" href="#концепция" aria-label="Permalink to &quot;Концепция&quot;">​</a></h2><p>Глобальные поля используются для данных, которые нужны на всех страницах: телефон компании, адрес, логотип, ссылки на соцсети и т.д. Вместо дублирования этих данных в каждом блоке, они задаются один раз и вызываются в любом шаблоне.</p><h2 id="использование-в-шаблонах" tabindex="-1">Использование в шаблонах <a class="header-anchor" href="#использование-в-шаблонах" aria-label="Permalink to &quot;Использование в шаблонах&quot;">​</a></h2><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ ex.global_fld(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;phone&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) }}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ ex.global_fld(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;company-logo&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) }}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ ex.global_fld(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;address&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) }}</span></span></code></pre></div><h2 id="типы-полеи" tabindex="-1">Типы полей <a class="header-anchor" href="#типы-полеи" aria-label="Permalink to &quot;Типы полей&quot;">​</a></h2><p>Глобальные поля поддерживают все те же типы, что и поля блоков/рубрик: string, text, image, select и др. Подробнее см. <a href="./../fields/">Поля</a>.</p><h2 id="импорт-и-экспорт" tabindex="-1">Импорт и экспорт <a class="header-anchor" href="#импорт-и-экспорт" aria-label="Permalink to &quot;Импорт и экспорт&quot;">​</a></h2><p>Глобальные поля включаются в импорт/экспорт быстрых настроек для переноса между проектами.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./../fields/">Поля</a> — все типы полей</li><li><a href="./preset-fields.html">Пресеты полей</a> — готовые наборы полей</li></ul>`,12)])])}const g=s(t,[["render",n]]);export{k as __pageData,g as default};
